const PLANNING_BASE6={fresh,validateSave,spend,nextWeek,collectDigest6,activateOpening6,productionHold5,foodBudgetPay5};
const PLAN_CATEGORIES6={expansion:'Expanze a vybavení',production:'Výroba a zásoby',people:'Nábor a rozvoj lidí',marketing:'Značky a marketing'};
const PLAN_LABELS6={expandProperty18:'Rozšíření prostoru kavárny',startOpening6:'Příprava nového provozu',orderSupplierCoffee6:'Dodávka hotové kávy',signCoffeeAgreement6:'Sjednání dodavatele kávy',prepareOpeningWeek6:'Sjednaný nábor a kontrola přípravy',processSupply:'Sjednané odběry zrn',settleProcurement5:'Splatné dodavatelské faktury',runBrandCampaigns5:'Probíhající kampaň',roastBatch:'Zpracování pražicí šarže',placeProcurementQuote5:'Objednávka kávových zrn',enrollAcademy6:'Kurz vlastní akademie',hireBarista5:'Nábor baristy',trainBarista5:'Školení baristy',leaseOffice6:'Sjednání kanceláře',buyAcademy6:'Pořízení akademie',packProduct6:'Balení vlastní kávy',shipProduct6:'Doprava balené kávy',buyFoodRaw5:'Suroviny pekárny'};
let planScopeContext6=null,planTransfer6=false,planWeekly6=false;
function ensurePlanning6(v){if(v.planning6===undefined)v.planning6={current:null,archive:[]};return v;}
fresh=function(...a){return ensurePlanning6(PLANNING_BASE6.fresh(...a));};ensurePlanning6(state);
function planRemaining6(category,v=state){const p=v.planning6?.current;return p?Math.max(0,p.budgets[category]-p.spent[category]):Infinity;}
function planAllowed6(category,amount){const p=state.planning6?.current;return !p||!p.enforce||amount<=planRemaining6(category)+.001;}
function planBook6(category,amount,label,mandatory=false){const p=state.planning6?.current;if(!p||planTransfer6||amount<=0)return;p.spent[category]+=amount;p.events.push({week:state.week,category,amount,label:String(label).slice(0,80),mandatory});while(p.events.length>160){const old=p.events.shift();p.carried[old.category]+=old.amount;}}
function planGuard6(category,amount){if(!planAllowed6(category,amount))throw Error('Čtvrtletní rozpočet: '+PLAN_CATEGORIES6[category]+' má zbývajících '+money(planRemaining6(category))+'. Změň plán firmy ve Financích.');}
spend=function(amount){const c=planScopeContext6;if(c&&!planTransfer6&&!c.mandatory)planGuard6(c.category,amount);PLANNING_BASE6.spend(amount);if(c){planBook6(c.category,amount,c.label,c.mandatory);c.booked+=amount;}};
function planScope6(category,label,fn,mandatory=false){const previous=planScopeContext6,before=state.cash,root=state,c={category,label,mandatory,booked:0};planScopeContext6=c;try{const result=fn();const direct=Math.max(0,before-state.cash-c.booked);if(state===root&&direct>.001)planBook6(category,direct,label,mandatory);return result;}finally{if(previous&&state===root)previous.booked+=c.booked+Math.max(0,before-state.cash-c.booked);planScopeContext6=previous;}}
function planWrap6(name,category,mandatory=false){const base=globalThis[name];if(typeof base!=='function')return;globalThis[name]=function(...args){return planScope6(category,PLAN_LABELS6[name]||PLAN_CATEGORIES6[category],()=>base(...args),mandatory);};}
for(const name of ['expandProperty18','startOpening6','buyOffice','leaseOffice6','buyEstate','expandEstate','irrigation','buyWarehouse','buyEquipment','buyEquipmentModel5','applyDesign5','upgradeRoaster','acquireRival','bidAuction','buyAcademy6'])planWrap6(name,'expansion');
for(const name of ['orderSupplierCoffee6','signCoffeeAgreement6','orderBeans','buyFoodRaw5','packProduct6','shipProduct6','developProduct6','retestProduct6','manualRoast','roastBatch','signSupply','buyProcurement5','signProcurement5','placeProcurementQuote5'])planWrap6(name,'production');
for(const name of ['hire','hireCandidate','hireBarista5','hireExecutive5','hireAcademyBaker6','hireAcademyTrainer6','enrollAcademy6','trainPerson','trainBarista5','promoteBarista5','setBakery5','researchBlend'])planWrap6(name,'people');
for(const name of ['createBrand','commitBrandIdentity5','rebrandStore5','commitCoffeeLabel5','startBrandCampaign5','startTrial4','enterCompetition4'])planWrap6(name,'marketing');
// These are fees in already signed preparation / invoices / active campaigns.
planWrap6('processSupply','production',true);planWrap6('prepareOpeningWeek6','people',true);planWrap6('settleProcurement5','production',true);planWrap6('runBrandCampaigns5','marketing',true);
activateOpening6=function(...a){const old=planTransfer6;planTransfer6=true;try{return PLANNING_BASE6.activateOpening6(...a);}finally{planTransfer6=old;}};
productionHold5=function(r,cost,...a){return PLANNING_BASE6.productionHold5(r,cost,...a)||(!planAllowed6('production',cost)?'čtvrtletní rozpočet výroby je vyčerpán':null);};
const PLAN_EXPRESS_RECORD6=recordSupplyExpress5;
recordSupplyExpress5=function(origin,kg,cost){const result=PLAN_EXPRESS_RECORD6(origin,kg,cost);planBook6('production',cost,'Expresní nákup zrn '+origin);return result;};
foodBudgetPay5=function(owner,amount){if(!planAllowed6('production',amount))return false;const result=PLANNING_BASE6.foodBudgetPay5(owner,amount);if(result)planBook6('production',amount,'Denní jídlo, suroviny a doprava');return result;};
const PLAN_DECIDE6=decidePlan4;
decidePlan4=function(id,approve,...a){const p=state.empire.plans.find(p=>p.id===id),s=p&&state.stores.find(s=>s.id===p.store);if(approve&&p?.action.kind==='staff'&&s?.crew)planGuard6('people',crewStaffQuote5(s,p.action.target).cost);return PLAN_DECIDE6(id,approve,...a);};
const PLAN_SUPPLY_ORDERS6=placeSupplyOrders5;
placeSupplyOrders5=function(orders,reserve=2,expected){const q=supplyOrderQuote5(orders,reserve);planGuard6('production',q.total);return PLAN_SUPPLY_ORDERS6(orders,reserve,expected);};
function planDefaultData6(){return {goals:{profit:0,revenue:0,stores:Math.max(1,state.stores.length),quality:75,reserve:2},budgets:{expansion:350000,production:100000,people:50000,marketing:20000},enforce:true};}
function planValidData6(d){return d&&typeof d.enforce==='boolean'&&d.goals&&d.budgets&&Object.keys(PLAN_CATEGORIES6).every(k=>Number.isInteger(d.budgets[k])&&d.budgets[k]>=0&&d.budgets[k]<=1e9)&&Number.isInteger(d.goals.profit)&&Math.abs(d.goals.profit)<=1e9&&Number.isInteger(d.goals.revenue)&&d.goals.revenue>=0&&d.goals.revenue<=1e10&&Number.isInteger(d.goals.stores)&&d.goals.stores>=0&&d.goals.stores<=LOCATIONS.length&&Number.isInteger(d.goals.quality)&&d.goals.quality>=0&&d.goals.quality<=100&&Number.isInteger(d.goals.reserve)&&d.goals.reserve>=0&&d.goals.reserve<=13;}
function planQuote6(data){if(!planValidData6(data))throw Error('Zkontroluj cíle a čtyři nezáporné rozpočty.');const p=state.planning6?.current;return {data:JSON.parse(JSON.stringify(data)),week:state.week,cash:state.cash,start:p?.start||state.week,end:p?.end||state.week+12,revision:p?.revisions.length||0,spent:p?{...p.spent}:Object.fromEntries(Object.keys(PLAN_CATEGORIES6).map(k=>[k,0]))};}
function setCompanyPlan6(data,expected){guard();const q=planQuote6(data);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Plán nebo výdaje se změnily. Obnov přehled.');let p=state.planning6.current;if(!p){p={start:q.start,end:q.end,goals:{...data.goals},budgets:{...data.budgets},enforce:data.enforce,spent:{...q.spent},carried:Object.fromEntries(Object.keys(PLAN_CATEGORIES6).map(k=>[k,0])),revisions:[],events:[],weeks:[],last:null};state.planning6.current=p;}if(p.revisions.length>=40)throw Error('V jednom období lze plán upravit nejvýše 40krát.');p.revisions.push({week:state.week,goals:{...data.goals},budgets:{...data.budgets},enforce:data.enforce});Object.assign(p,{goals:{...data.goals},budgets:{...data.budgets},enforce:data.enforce});log('Čtvrtletní plán firmy', 'T'+p.start+'–'+p.end+'. Revize nemění dosavadní výdaje ani hotovost.');return p;}
function planAssessment6(p=state.planning6?.current){if(!p)return null;const weeks=p.weeks,latest=weeks.at(-1),profit=weeks.reduce((n,w)=>n+w.profit,0),revenue=weeks.reduce((n,w)=>n+w.revenue,0),operating=weeks.reduce((n,w)=>n+w.operating,0),done=weeks.length;const rows=[['Výsledek za období',p.goals.profit,profit],['Tržby za období',p.goals.revenue,revenue],['Kavárny na konci období',p.goals.stores,latest?.stores??state.stores.length],['Kvalita obsloužených hostů',p.goals.quality,latest?.quality??0],['Rezerva v týdnech závazků',p.goals.reserve,latest?.reserve??(weeklyFixed()?state.cash/weeklyFixed():13)]];const notes=[];if(done){notes.push('Skutečné tržby '+money(revenue)+' proti cíli '+money(p.goals.revenue)+'. Provoz a daň '+money(operating)+', spotřebovaná káva '+money(weeks.reduce((n,w)=>n+w.cogs,0))+', odpis zásob '+money(weeks.reduce((n,w)=>n+w.waste,0))+'.');const missing=weeks.reduce((n,w)=>n+w.stockLost,0),capacity=weeks.reduce((n,w)=>n+w.capacityLost,0);if(missing)notes.push(missing+' hostů nebylo obslouženo kvůli chybějící kávě; příjem za tyto hosty se do skutečných tržeb nezapočítal.');if(capacity)notes.push(capacity+' hostů se nevešlo do provozní kapacity; prověř směny, čekání a vybavení.');for(const k of Object.keys(PLAN_CATEGORIES6))if(p.spent[k]>p.budgets[k])notes.push(PLAN_CATEGORIES6[k]+': přesah '+money(p.spent[k]-p.budgets[k])+'. Platby již sjednaných závazků pokračují i při vyčerpaném limitu; podrobnosti jsou v platebním záznamu.');}return {done,profit,revenue,operating,notes,rows:rows.map(([label,target,actual])=>({label,target,actual,variance:actual-target})),budgets:Object.keys(PLAN_CATEGORIES6).map(category=>({category,target:p.budgets[category],actual:p.spent[category],variance:p.spent[category]-p.budgets[category]})),explanation:done?'Výsledek zahrnuje skutečné tržby, spotřebu zásob, provoz, odpisy a daň. Rozvojové rozpočty sledují platby za nové kroky; již sjednané závazky se platí dál.':'První skutečný týden ještě není uzavřen.'};}
function closePlanWeek6(h){const p=state.planning6?.current;if(!p||p.weeks.some(w=>w.week===h.week))return;const served=state.stores.reduce((n,s)=>n+(s.last?.served||0),0),quality=served?state.stores.reduce((n,s)=>n+(s.last?.served||0)*(s.last?.quality||0),0)/served:0;p.weeks.push({week:h.week,profit:h.profit,revenue:h.revenue,operating:h.expenses,cogs:h.cogs,waste:h.spoil,stockLost:state.stores.reduce((n,s)=>n+(s.last?.stockLost||0),0),capacityLost:state.stores.reduce((n,s)=>n+(s.last?.capacityLost||0),0),stores:state.stores.length,quality,reserve:weeklyFixed()?Math.min(13,state.cash/weeklyFixed()):13});p.last=planAssessment6(p);if(h.week>=p.end){p.closed=h.week;state.planning6.archive.push(p);state.planning6.archive=state.planning6.archive.slice(-8);state.planning6.current=null;}return p;}
collectDigest6=function(h,...a){const result=PLANNING_BASE6.collectDigest6(h,...a);const p=state.planning6?.current;if(p&&h.week>=p.end)result.items.push({category:'operations',key:'quarter-plan-'+p.start,title:'Čtvrtletní plán · uzavření T'+p.end,text:'Otevři cíle, skutečné rozvojové výdaje a rozklad změny výsledku.',view:'finance',target:'quarter',due:null,severity:1,pending:false});return result;};
nextWeek=function(...a){const previous=planWeekly6;planWeekly6=true;try{const h=PLANNING_BASE6.nextWeek(...a);closePlanWeek6(h);return h;}finally{planWeekly6=previous;}};
validateSave=function(input){const v=PLANNING_BASE6.validateSave(input);ensurePlanning6(v);const fail=()=>{throw Error('Soubor obsahuje neplatný firemní plán.');},n=(x,min=-1e12,max=1e12)=>Number.isFinite(x)&&x>=min&&x<=max,int=(x,min,max)=>Number.isInteger(x)&&n(x,min,max),root=v.planning6;if(!root||!Array.isArray(root.archive)||root.archive.length>8)fail();const periods=[...root.archive,...(root.current?[root.current]:[])];let lastEnd=0;for(const p of periods){if(!p||!int(p.start,1,v.week)||p.end!==p.start+12||p.start<=lastEnd||!planValidData6(p)||!p.spent||!p.carried||Object.keys(PLAN_CATEGORIES6).some(k=>!n(p.spent[k],0)||!n(p.carried[k],0))||!Array.isArray(p.revisions)||!p.revisions.length||p.revisions.length>40||!Array.isArray(p.events)||p.events.length>160||!Array.isArray(p.weeks)||p.weeks.length>13)fail();lastEnd=p.end;for(const r of p.revisions)if(!planValidData6(r)||!int(r.week,p.start,Math.min(p.end,v.week)))fail();const rev=p.revisions.at(-1);if(JSON.stringify(p.goals)!==JSON.stringify(rev.goals)||JSON.stringify(p.budgets)!==JSON.stringify(rev.budgets)||p.enforce!==rev.enforce)fail();for(const e of p.events)if(!int(e.week,p.start,Math.min(p.end,v.week))||!Object.hasOwn(PLAN_CATEGORIES6,e.category)||!n(e.amount,0)||typeof e.label!=='string'||e.label.length>80||typeof e.mandatory!=='boolean')fail();for(const k of Object.keys(PLAN_CATEGORIES6))if(Math.abs(p.carried[k]+p.events.filter(e=>e.category===k).reduce((a,e)=>a+e.amount,0)-p.spent[k])>.01)fail();for(let i=0;i<p.weeks.length;i++){const w=p.weeks[i];if(w.week!==p.start+i||w.week>=v.week||!['profit','revenue','operating','cogs','waste','stockLost','capacityLost','quality','reserve','stores'].every(k=>n(w[k]))||!int(w.stores,0,LOCATIONS.length)||!n(w.quality,0,100))fail();}if(p===root.current){if(p.closed!==undefined||p.end<v.week||p.weeks.length!==v.week-p.start)fail();}else if(p.closed!==p.end||p.closed>=v.week||p.weeks.length!==13)fail();}return v;};
